document.addEventListener('DOMContentLoaded', () => {
  // Custom cursor
  const dot = document.getElementById('cursorDot');
  const ring = document.getElementById('cursorRing');
  let mouseX = -100, mouseY = -100;
  let ringX = -100, ringY = -100;

  document.addEventListener('mousemove', (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;
    dot.style.left = mouseX + 'px';
    dot.style.top  = mouseY + 'px';
    document.body.classList.remove('cursor-hidden');
  });

  document.addEventListener('mouseleave', () => document.body.classList.add('cursor-hidden'));
  document.addEventListener('mouseenter', () => document.body.classList.remove('cursor-hidden'));

  // Ring follows with smooth lag
  (function animateRing() {
    ringX += (mouseX - ringX) * 0.12;
    ringY += (mouseY - ringY) * 0.12;
    ring.style.left = ringX + 'px';
    ring.style.top  = ringY + 'px';
    requestAnimationFrame(animateRing);
  })();

  // Hover state on interactive elements
  const interactives = 'a, button, [onclick], input, label, .article-row, .tag';
  document.addEventListener('mouseover', (e) => {
    if (e.target.closest(interactives)) document.body.classList.add('cursor-hover');
  });
  document.addEventListener('mouseout', (e) => {
    if (e.target.closest(interactives)) document.body.classList.remove('cursor-hover');
  });

  // Click state
  document.addEventListener('mousedown', () => document.body.classList.add('cursor-clicking'));
  document.addEventListener('mouseup',   () => document.body.classList.remove('cursor-clicking'));

  // Hero headline
  const headline = document.querySelector('.hero__headline');
  setTimeout(() => headline.classList.add('visible'), 300);

  // Hero tilt
  const hero = document.getElementById('hero');
  const content = hero.querySelector('.hero__content');
  hero.addEventListener('mousemove', (e) => {
    const rect = hero.getBoundingClientRect();
    const dx = (e.clientX - (rect.left + rect.width / 2)) / (rect.width / 2);
    const dy = (e.clientY - (rect.top + rect.height / 2)) / (rect.height / 2);
    content.style.transform = `perspective(1200px) rotateX(${dy * -1.5}deg) rotateY(${dx * 1.5}deg)`;
  });
  hero.addEventListener('mouseleave', () => {
    content.style.transition = 'transform 0.6s cubic-bezier(0.22,1,0.36,1)';
    content.style.transform = 'perspective(1200px) rotateX(0deg) rotateY(0deg)';
  });
  hero.addEventListener('mouseenter', () => {
    content.style.transition = 'transform 0.1s linear';
  });

  // Header scroll
  const header = document.getElementById('header');
  window.addEventListener('scroll', () => {
    header.classList.toggle('scrolled', window.scrollY > 20);
  });

  // Scroll reveal
  const reveals = document.querySelectorAll('.row, .article-row, .contact, .projects-empty, .process-card');
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry, i) => {
      if (entry.isIntersecting) {
        setTimeout(() => entry.target.classList.add('visible'), i * 80);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.08 });
  reveals.forEach(el => observer.observe(el));

  // Theme toggle
  const themeToggle = document.getElementById('themeToggle');
  let dark = false;
  themeToggle.addEventListener('click', () => {
    dark = !dark;
    if (dark) {
      document.documentElement.setAttribute('data-theme', 'dark');
    } else {
      document.documentElement.removeAttribute('data-theme');
    }
    themeToggle.innerHTML = dark
      ? `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>`
      : `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>`;
  });
});

function toggleAccordion(trigger) {
  const card = trigger.closest('.process-card');
  const isOpen = card.classList.contains('open');
  document.querySelectorAll('.process-card.open').forEach(c => c.classList.remove('open'));
  if (!isOpen) card.classList.add('open');
}

function openArticle() {
  document.getElementById('articleOverlay').classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeArticle() {
  document.getElementById('articleOverlay').classList.remove('active');
  document.body.style.overflow = '';
}

// ── Polaroid hover gallery ──
(function() {

const LABELS = ['', '', '', '', '', '', ''];

const POLAROID_IMAGES = [
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,"
];

const hero = document.getElementById('hero');
if (!hero) return;

let pool = [];
let active = [];
let spawnTimer = null;
let isHovering = false;
let mouseX = 0, mouseY = 0;
let lastSpawn = 0;
const THROTTLE = 220; // ms between spawns
const MAX_ACTIVE = 6;
let imgIndex = 0;

function createPolaroid() {
  const el = document.createElement('div');
  el.className = 'polaroid';
  const img = document.createElement('img');
  img.className = 'polaroid__img';
  const lbl = document.createElement('div');
  lbl.className = 'polaroid__label';
  el.appendChild(img);
  el.appendChild(lbl);
  document.body.appendChild(el);
  return { el, img, lbl };
}

function spawnPolaroid(x, y) {
  const now = Date.now();
  if (now - lastSpawn < THROTTLE) return;
  if (active.length >= MAX_ACTIVE) removePolaroid(active[0]);
  lastSpawn = now;

  const p = pool.length ? pool.pop() : createPolaroid();
  const rot = (Math.random() * 26 - 13).toFixed(1);
  const offsetX = (Math.random() * 60 - 30);
  const offsetY = (Math.random() * 40 - 20);
  const posX = x + offsetX - 80;
  const posY = y + offsetY - 110;
  const baseTransform = `rotate(${rot}deg)`;

  p.img.src = POLAROID_IMAGES[imgIndex % POLAROID_IMAGES.length];
  p.lbl.textContent = LABELS[imgIndex % LABELS.length];
  imgIndex++;

  p.el.style.left = posX + 'px';
  p.el.style.top  = posY + 'px';
  p.el.style.setProperty('--p-base', baseTransform);
  p.el.style.transform = baseTransform;
  p.el.classList.remove('fading', 'dropping');
  void p.el.offsetWidth; // force reflow
  p.el.classList.add('dropping');

  active.push(p);
}

function removePolaroid(p) {
  const idx = active.indexOf(p);
  if (idx !== -1) active.splice(idx, 1);
  p.el.classList.remove('dropping');
  void p.el.offsetWidth;
  p.el.classList.add('fading');
  p.el.addEventListener('animationend', () => {
    p.el.classList.remove('fading');
    p.el.style.opacity = '0';
    pool.push(p);
  }, { once: true });
}

function clearAll() {
  [...active].forEach(removePolaroid);
}

hero.addEventListener('mouseenter', () => { isHovering = true; });
hero.addEventListener('mouseleave', () => {
  isHovering = false;
  clearAll();
});
hero.addEventListener('mousemove', (e) => {
  mouseX = e.clientX;
  mouseY = e.clientY;
  spawnPolaroid(mouseX, mouseY);
});

})();
